import{_ as d,o as e,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"mini-git 与真 git 的差异","description":"","frontmatter":{},"headers":[],"relativePath":"mini-git-ts-course/divergence.md","filePath":"mini-git-ts-course/docs/divergence.md"}'),i={name:"mini-git-ts-course/divergence.md"};function h(o,t,s,n,l,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mini-git-与真-git-的差异" tabindex="-1">mini-git 与真 git 的差异 <a class="header-anchor" href="#mini-git-与真-git-的差异" aria-label="Permalink to &quot;mini-git 与真 git 的差异&quot;">​</a></h1><p>正文每处「mini-git 从简/不实现」的集中登记。分两类:<strong>简化项</strong>(mini-git 换了一种更简单的做法)与<strong>未实现项</strong>(真 git 有、mini-git 没造)。每条注明出处章节;对拍口径以各章正文为准。</p><h2 id="未实现项" tabindex="-1">未实现项 <a class="header-anchor" href="#未实现项" aria-label="Permalink to &quot;未实现项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>未实现能力</th><th>真 git 那边是什么</th><th>mini-git 现状</th><th>出处</th></tr></thead><tbody><tr><td>packfile 与 delta 压缩</td><td>对象打包成 pack + idx,相近对象存增量,<code>git gc</code> 负责整理</td><td>全书只做松散对象,一个对象一个文件</td><td><a href="./02-content-addressed-store.html">第 2 章</a>、<a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>多轮协商与 want/have 对话</td><td>引用发现之后还有能力协商、多轮 want/have、side-band 进度</td><td>一轮定案:清单 → 请求 → 判词</td><td><a href="./10-wire-protocol.html">第 10 章</a>、<a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>rebase / cherry-pick / amend</td><td>提交图上的重放与改写</td><td>未造;第 4 章只演示了改写历史的哈希雪崩</td><td><a href="./04-commit-dag.html">第 4 章</a>、<a href="./12-end-to-end.html">第 12 章</a></td></tr><tr><td>reflog 与 gc</td><td>引用移动的流水账;<code>gc</code> 清理不可达对象,reflog 兜底 30/90 天</td><td>不写 reflog,游离提交无兜底(可达性判定与真 git 一致)</td><td><a href="./08-merge-base.html">第 8 章</a></td></tr><tr><td>submodule / gitlink(160000)</td><td>嵌套仓库挂成 tree 条目</td><td>不产不解</td><td><a href="./03-tree-snapshots.html">第 3 章</a></td></tr><tr><td>符号链接对象(120000)</td><td>tree 条目的一种模式</td><td>不产不解</td><td><a href="./03-tree-snapshots.html">第 3 章</a></td></tr><tr><td>tag 引用</td><td>refs/tags 与指向 tag 对象</td><td>只认 refs/heads;广告也只列分支</td><td><a href="./06-refs-branches.html">第 6 章</a>、<a href="./10-wire-protocol.html">第 10 章</a></td></tr><tr><td>冲突的 index 三阶段(stage 1/2/3)</td><td>冲突路径挂三条条目,<code>git ls-files -u</code> 可查</td><td>index 只登记带标记稿单份,flags 高 4 位非零判损坏</td><td><a href="./05-index-file.html">第 5 章</a>、<a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>MERGE_HEAD 与冲突收尾</td><td>冲突解决后的提交仍是 merge(双父)</td><td>不写 MERGE_HEAD,收尾提交是单父</td><td><a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>refspec 与 <code>--force</code></td><td>push/fetch 可指定映射与强推</td><td>无 refspec;push 只有 ff 一档,非快进即拒</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr></tbody></table><h2 id="简化项-做法不同-口径已对拍或声明" tabindex="-1">简化项(做法不同,口径已对拍或声明) <a class="header-anchor" href="#简化项-做法不同-口径已对拍或声明" aria-label="Permalink to &quot;简化项(做法不同,口径已对拍或声明)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>真 git</th><th>mini-git</th><th>出处</th></tr></thead><tbody><tr><td>对象名输入</td><td>支持缩写(前缀即可)</td><td>只认完整 40 位</td><td><a href="./02-content-addressed-store.html">第 2 章</a>、<a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>仓库发现</td><td>向上层目录找 .git</td><td>只认当前目录</td><td><a href="./02-content-addressed-store.html">第 2 章</a></td></tr><tr><td>init 骨架</td><td>完整布局(config/hooks/info 等)</td><td>只建 objects、refs/heads、HEAD 三件</td><td><a href="./02-content-addressed-store.html">第 2 章</a></td></tr><tr><td>可执行位</td><td>平台相关</td><td>Windows 下恒 100644,检出不设执行位</td><td><a href="./03-tree-snapshots.html">第 3 章</a></td></tr><tr><td>提交可选头</td><td>gpgsig、encoding 等</td><td>不解析,遇到判损坏</td><td><a href="./04-commit-dag.html">第 4 章</a></td></tr><tr><td>log 日期/双父行</td><td>换算日历,双父多打 Merge 行</td><td>打 Unix 秒原文;同刻次序自定(发现序、父一先于父二)</td><td><a href="./04-commit-dag.html">第 4 章</a></td></tr><tr><td>身份来源</td><td>user.name/user.email 配置链</td><td>环境变量,缺省 mini-git;committer 恒等于 author</td><td><a href="./04-commit-dag.html">第 4 章</a></td></tr><tr><td>write-tree 无 index 时</td><td>写空树 <code>4b825dc6…</code></td><td>退回整目录扫描(第 3 章老路)</td><td><a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>index 扩展与 stat</td><td>读写 TREE 等扩展;stat 字段用于跳步</td><td>不读不写扩展;stat 存而不用,比对老实重算</td><td><a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>add 范围</td><td>展开目录、可暂存删除</td><td>只收文件路径</td><td><a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>status 输出</td><td>英文三段 + 分支行</td><td>中文简化段</td><td><a href="./05-index-file.html">第 5 章</a></td></tr><tr><td>checkout 安全</td><td>脏改动会被覆盖时拒绝</td><td>无条件覆盖被跟踪文件,未跟踪保留</td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>commit 空清单</td><td>报「nothing to commit」</td><td>提交空树(行为被测试钉死)</td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>branch 起点</td><td><code>branch &lt;name&gt; &lt;start&gt;</code></td><td>不收起点参数</td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>packed-refs</td><td>引用可打包</td><td>只有松散引用文件</td><td><a href="./06-refs-branches.html">第 6 章</a></td></tr><tr><td>diff 算法</td><td>默认 Myers(可换 patience/histogram)</td><td>朴素 LCS 动态规划;平手取「删在加前」</td><td><a href="./07-line-diff.html">第 7 章</a></td></tr><tr><td>diff 输出</td><td>index 行、函数名提示、<code>\\ No newline</code>、二进制检测、-U</td><td>都不做;上下文固定 3;文件尾假定有换行</td><td><a href="./07-line-diff.html">第 7 章</a></td></tr><tr><td>merge-base 多候选</td><td>筛 best,规范 unspecified</td><td>取 committer 时间戳最新、同刻哈希字典序最小;无 <code>--all</code></td><td><a href="./08-merge-base.html">第 8 章</a></td></tr><tr><td>merge-base 出口</td><td><code>--is-ancestor</code> 用退出码,无祖先进位 1</td><td>文字作答,无公共祖先抛可读的错</td><td><a href="./08-merge-base.html">第 8 章</a></td></tr><tr><td>冲突块细化</td><td>zealous refine、相邻冲突归并</td><td>不做;判定表「严格在前才自动、相触即冲突」</td><td><a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>冲突报告</td><td>退出码 = 冲突块数</td><td>文本报告(命令层只产文本的既有口径)</td><td><a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>合并前提检查</td><td>未提交改动可能阻止合并</td><td>不检查,无条件合并;模式冲突取 ours</td><td><a href="./09-three-way-merge.html">第 9 章</a></td></tr><tr><td>协议承载</td><td>SSH / HTTP(S) / git://(9418)</td><td>自有裸 TCP,默认 9419,不与真 git 互通</td><td><a href="./10-wire-protocol.html">第 10 章</a></td></tr><tr><td>能力协商</td><td>引用行带 NUL + capabilities</td><td>不发</td><td><a href="./10-wire-protocol.html">第 10 章</a></td></tr><tr><td>对象线上形状</td><td>packfile</td><td>自定帧:「类型 哈希 字节数」头 + 体帧,收方重算哈希对账</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>被拒推送</td><td>协商期即拒,对象不过线</td><td>对象先落库再判 ff,被拒对象成 unreachable</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>推检出分支</td><td>默认拒收非当前分支的推送</td><td>不设卡</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>远端命名</td><td><code>remote.&lt;名&gt;.fetch</code> 配置</td><td>从地址折成 <code>&lt;主机&gt;-&lt;端口&gt;</code></td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr><tr><td>服务端缓冲</td><td>流式</td><td>请求整段内存缓冲,5 秒无下文送客</td><td><a href="./11-sync-operations.html">第 11 章</a></td></tr></tbody></table><h2 id="对拍口径备注" tabindex="-1">对拍口径备注 <a class="header-anchor" href="#对拍口径备注" aria-label="Permalink to &quot;对拍口径备注&quot;">​</a></h2><ul><li>与真 git 的对拍一律用 <code>git -c core.autocrlf=false</code> 或 <code>--no-filters</code>,避开行尾过滤(Windows 下尤其);金样哈希全部由固定输入(同身份、同时间戳)固化,跨机器逐字符成立。</li><li><code>pull = fetch + merge</code> 的流行说法按现行 git-pull 文档校准:默认档是 <code>--ff-only</code>,merge 是 <code>--no-rebase</code> 一档(见<a href="./12-end-to-end.html">第 12 章</a>)。</li><li>重复行加平手口径的极端构造下,行对齐可能挪位,连「干净/冲突」判定都可能翻转(第 7 章 diff 口径的下游效应)。</li></ul>',8)])])}const g=d(i,[["render",h]]);export{m as __pageData,g as default};
